        )

    def domain_source_catalog(
        self,
        source_id: str,
        *,
        collection_path: str | None = None,
    ) -> dict[str, Any]:
        """Read one adopted source catalog without expanding unrelated facts."""

        return self._domain_query(
            "source_catalog",
