        )

    def domain_fact_body(
        self,
        fact_id: str,
        *,
        source_id: str | None = None,
        collection_id: str | None = None,
        collection_path: str | None = None,
        source_path: str | None = None,
    ) -> dict[str, Any]:
        """Read exactly one adopted canonical domain fact."""

        return self._domain_query(
            "fact_body",
            fact_id,
